/** One bounded topology-free sparse extent plan. */
export interface NativeWorkspaceExtentPlan {
  spans: Array<NativeWorkspaceExtentSpan>
}

/** One topology-free sparse extent span. */
export interface NativeWorkspaceExtentSpan {
  offset: bigint
  length: bigint
  sourceEnd: bigint
  kind: string
}

/** One durable workspace-lineage record. */
export interface NativeWorkspaceLineageRecord {
  version: number
  revision: bigint
  workspaceId: Buffer
  workspaceName: string
  parentWorkspaceId?: Buffer
  parentWorkspaceName?: string
  forkGeneration: Buffer
  initialGeneration: Buffer
}

/** Scalar cross-profile metadata and opaque-payload presence. */
export interface NativeWorkspaceMetadata {
  posixMode?: number
  posixUid?: number
  posixGid?: number
  posixFlags?: bigint
  windowsAttributes?: number
  createdNs?: bigint
  modifiedNs?: bigint
  accessedNs?: bigint
  changedNs?: bigint
  hasNamedAttributes: boolean
  hasAcl: boolean
  hasSecurityDescriptor: boolean
}

/** Explicit native workspace mount policy. */
export interface NativeWorkspaceMountOptions {
  /** Whether the mount accepts authored changes. */
  writable: boolean
  /** Exact workspace directory projected as the mount root. */
  subdirectory: string
  /** `close-and-sync`, `per-mutation`, or `manual`. */
  publication: string
}

/** One exact encoded directory name. */
export interface NativeWorkspaceName {
  encoding: string
  bytes: Buffer
}

/** Workspace-aware final-close outcome. */
export interface NativeWorkspaceOperationFinish {
  /** `still-active`, `already-closed`, or `reconciled`. */
  kind: string
  /** Live lease count for `still-active`. */
  remaining?: number
  /** Core rebase result for `reconciled`. */
  rebase?: NativeWorkspaceRebaseResult
}

/** Terminal result of advancing a fork onto its source workspace. */
export interface NativeWorkspaceRebaseResult {
  /**
   * `rebased`, `already-rebased`, `current`, `stale`, `conflicted`, `fenced`,
   * or `idempotency-conflict`.
   */
  status: string
  /** Exact fork generation for generation-bearing outcomes. */
  generationId?: Buffer
  /** Stable path-independent conflict regions. */
  conflicts: Array<NativeMergeConflict>
  /** Whether additional conflicts exceeded the retained result bound. */
  truncated: boolean
}

/** One exact customer-visible path stat without storage topology. */
export interface NativeWorkspaceStat {
  fileId: Buffer
  kind: string
  linkCount: bigint
  logicalBytes?: bigint
  metadata: NativeWorkspaceMetadata
}
